                      <td><span className={`badge ${s.status==="completed"?"badge-green":"badge-blue"}`}>{s.status}</span></td>
                      <td>{s.status==="scheduled" && <button className="btn btn-sm btn-outline" onClick={() => markSessionDone(s)}>Mark Done</button>}</td>
                    </tr>
                  ))}</tbody>
                </table>
              }
            </div>
          </>
        )}

