              </div>
            </div>

            {/* Student selector */}
            {!selectedStudent && (
              <div className="grid-2">
                {students.length === 0
                  ? <div className="card"><div className="empty-state"><div className="empty-icon">👥</div><p>No students yet.</p></div></div>
